-- Generated by rice-render for {{ meta.title }}: lualine theme "rice".
-- Paper Night: black card with gel-blue writing; the mode is a strip of
-- adhesive (yellow normally, pink when changing text, mint when selecting)
-- with the sheet's dark showing through the letters. lualine@light.lua is the day.
local c = {
  card     = "{{ colors.card }}",
  paper    = "{{ colors.paper }}",
  ink      = "{{ colors.ink }}",
  carbon   = "{{ colors.carbon }}",
  graphite = "{{ colors.graphite }}",
  sticky   = "{{ colors.sticky }}",
  pink     = "{{ colors.pink }}",
  mint     = "{{ colors.mint }}",
  red      = "{{ colors.red }}",
}
local function mode(mark)
  return {
    a = { fg = c.paper, bg = mark, gui = "bold" },
    b = { fg = c.ink, bg = c.card },
    c = { fg = c.ink, bg = c.card },
  }
end
return {
  normal   = mode(c.sticky),
  insert   = mode(c.pink),
  visual   = mode(c.mint),
  replace  = { a = { fg = c.card, bg = c.red, gui = "bold" }, b = { fg = c.ink, bg = c.card }, c = { fg = c.ink, bg = c.card } },
  command  = { a = { fg = c.card, bg = c.ink, gui = "bold" }, b = { fg = c.ink, bg = c.card }, c = { fg = c.ink, bg = c.card } },
  terminal = mode(c.pink),
  inactive = { a = { fg = c.graphite, bg = c.card }, b = { fg = c.graphite, bg = c.card }, c = { fg = c.graphite, bg = c.card } },
}
